def icon(name): return ICONS[name]

def slug_url(filename): return f"{SITE}/{filename.replace('.html','')}" if filename != "index.html" else SITE + "/"

def jsonld(data):
    return '<script type="application/ld+json">' + json.dumps(data, ensure_ascii=False) + '</script>'

def org_schema():
    return {
      "@context":"https://schema.org", "@type":"HomeAndConstructionBusiness", "@id": SITE + "/#business",
      "name":"Master Glass Solutions", "url":SITE + "/", "telephone":"+12103703700", "email":EMAIL,
      "image": SITE + "/assets/hero-storefront.jpg",
      "address":{"@type":"PostalAddress","streetAddress":"108 Scheele Rd Unit 4","addressLocality":"Boerne","addressRegion":"TX","postalCode":"78015","addressCountry":"US"},
      "areaServed":[{"@type":"City","name":"Boerne"},{"@type":"City","name":"San Antonio"}],
      "description":"Commercial and residential glass installation, fabrication, repair, storefront, shower enclosure and custom glass services in Boerne and San Antonio, Texas.",
      "knowsAbout":["Residential glass","Commercial glass","Emergency glass repair","Storefront glass","Custom glass","Shower enclosures","Mirrors","Window glass replacement"]
    }

def breadcrumb(items):
    list_items = [{"@type":"ListItem", "position":1, "name":"Home", "item":SITE + "/"}]
    for n, file in items:
        list_items.append({"@type":"ListItem", "position":len(list_items)+1,"name":n,"item":slug_url(file)})
    return {"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":list_items}

def service_schema(name, description, filename):
    return {"@context":"https://schema.org","@type":"Service","@id":slug_url(filename)+"#service", "name":name,
      "description":description, "url":slug_url(filename), "provider":{"@id":SITE+"/#business"},
      "areaServed":[{"@type":"City","name":"Boerne"},{"@type":"City","name":"San Antonio"}],
      "serviceType":name}

def faq_schema(faqs):
    return {"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":q,"acceptedAnswer":{"@type":"Answer","text":a}} for q,a in faqs]}

def page_schema(extra=None, crumbs=None, faqs=None):
    schemas=[org_schema()]
    if extra: schemas.append(extra)
    if crumbs: schemas.append(breadcrumb(crumbs))
    if faqs: schemas.append(faq_schema(faqs))
    return "\n".join(jsonld(x) for x in schemas)

