def faq_section(faqs, title="Clear answers, before you commit", intro=None):
    intro_html=f'<p class="section-intro">{intro}</p>' if intro else ''
    items="".join(f'''<details><summary>{q}<span>+</span></summary><div class="faq-answer"><p>{a}</p></div></details>''' for q,a in faqs)
    return f'''<section class="section faq-section"><div class="shell faq-layout"><div>{eyebrow("FAQ")}<h2>{title}</h2>{intro_html}<a class="text-link" href="faq.html">See every question {icon("arrow")}</a></div><div class="faq-list">{items}</div></div></section>'''

def mini_cta(title="A precise next step starts with a clear conversation.", text="Tell us what you’re planning, repairing, or replacing. We’ll help you identify the right path.", urgent=False):
    primary = f'<a class="btn btn-alert" href="tel:{PHONE_LINK}">{icon("phone")} Call emergency support</a>' if urgent else cta_quote("Start your quote", "btn btn-light")
    secondary = cta_quote("Request a project estimate", "btn btn-ghost") if urgent else cta_call()
    return f'''<section class="section final-cta"><div class="final-rule"></div><div class="shell final-cta-grid"><div>{eyebrow("MASTER GLASS SOLUTIONS")}<h2>{title}</h2></div><div><p>{text}</p><div class="hero-actions">{primary}{secondary}</div></div></div></section>'''

